package main

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

func TestProbeSweep(t *testing.T) {
	store := NewStore(30 * time.Second)
	now := time.Unix(1000, 0)
	store.now = func() time.Time { return now }
	store.Create("a", "u1")
	now = time.Unix(1020, 0)
	store.Create("b", "u2")
	now = time.Unix(1040, 0) // a expired (1000+30), b live (1020+30=1050)
	store.Create("c", "u3")

	mux := http.NewServeMux()
	mux.HandleFunc("/admin/sweep", sweepHandler(store))
	mux.HandleFunc("/session", sessionHandler(store))

	rec := httptest.NewRecorder()
	mux.ServeHTTP(rec, httptest.NewRequest("POST", "/admin/sweep", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("sweep status = %d, want 200", rec.Code)
	}
	var body map[string]int
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("body not json: %v", err)
	}
	if body["swept"] != 1 {
		t.Fatalf("swept = %d, want 1", body["swept"])
	}
	if store.Len() != 2 {
		t.Fatalf("len after sweep = %d, want 2", store.Len())
	}
	if _, err := store.Get("a"); err == nil {
		t.Fatal("expired session survived sweep")
	}

	// Second sweep removes nothing.
	rec = httptest.NewRecorder()
	mux.ServeHTTP(rec, httptest.NewRequest("POST", "/admin/sweep", nil))
	var body2 map[string]int
	_ = json.Unmarshal(rec.Body.Bytes(), &body2)
	if body2["swept"] != 0 {
		t.Fatalf("second swept = %d, want 0", body2["swept"])
	}

	// Wrong method rejected.
	rec = httptest.NewRecorder()
	mux.ServeHTTP(rec, httptest.NewRequest("GET", "/admin/sweep", nil))
	if rec.Code != http.StatusMethodNotAllowed {
		t.Fatalf("GET sweep status = %d, want 405", rec.Code)
	}
}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_sweep_test.go ; exit $rc

